    sep_color = grid[sep_rows[0]][0]
    sep_cols = [c for c in range(w) if all(grid[r][c] == sep_color for r in range(h))]

    # Cell starts are positions not in separator rows/cols
    cell_rows = []
    r = 0
    while r < h:
        if r not in sep_rows:
            cell_rows.append(r)
            while r + 1 < h and (r + 1) not in sep_rows:
                r += 1
        r += 1

    cell_cols = []
    c = 0
    while c < w:
        if c not in sep_cols:
            cell_cols.append(c)
            while c + 1 < w and (c + 1) not in sep_cols:
                c += 1
        c += 1

    ch, cw = len(cell_rows), len(cell_cols)

    # Read cell colors
    cells = [[0] * cw for _ in range(ch)]
    for i, r0 in enumerate(cell_rows):
        r1 = sep_rows[i] if i < len(sep_rows) else h
        for j, c0 in enumerate(cell_cols):
            c1 = sep_cols[j] if j < len(sep_cols) else w
            vals = set()
            for r in range(r0, r1):
                for c in range(c0, c1):
                    if grid[r][c] != sep_color:
                        vals.add(grid[r][c])
            cells[i][j] = next(iter(vals)) if vals else 0

