    pos = {}
    for i in range(ch):
        for j in range(cw):
            v = cells[i][j]
            if v != 0:
                pos.setdefault(v, []).append((i, j))

    out = [row[:] for row in cells]

    def fill_segment(color, a, b):
        (r1, c1), (r2, c2) = a, b
        if r1 == r2:
            for c in range(min(c1, c2), max(c1, c2) + 1):
