                    if p[1] == q[1]:
                        col_pairs.append((p, q, abs(p[0] - q[0])))

            if len(row_pairs) == 1 and len(col_pairs) == 1:
                rp, cp = row_pairs[0], col_pairs[0]
                row_set = {rp[0], rp[1]}
                col_set = {cp[0], cp[1]}
                shared = list(row_set & col_set)
                if shared:
                    sr, sc = shared[0]
                    corner = (sr in (0, ch - 1)) and (sc in (0, cw - 1))
                    if corner:
                        fill_segment(color, rp[0], rp[1])
                        fill_segment(color, cp[0], cp[1])
                    else:
                        if rp[2] >= cp[2]:
                            fill_segment(color, rp[0], rp[1])
                        else:
                            fill_segment(color, cp[0], cp[1])
            else:
                best = None
                for p, q, d in row_pairs + col_pairs:
                    if best is None or d > best[2]:
                        best = (p, q, d)
                if best is not None:
                    fill_segment(color, best[0], best[1])

    # Reconstruct full grid
    res = [row[:] for row in grid]
    for i, r0 in enumerate(cell_rows):
